n=28
out=[[0]*n for _ in range(n)]
for i in range(n):
    if i in [4,9,14,19,24]: out[i]=[8]*n
    else:
        for j in [4,9,14,19,24]: out[i][j]=8
rooms=[(0,3),(5,8),(10,13),(15,18),(20,23),(25,27)]
for rr in range(6):
  for cc in range(6):
    col=0
    if (rr==1 and 0<=cc<=4) or (cc==0 and 1<=rr<=3): col+=2
    if cc==2 and 0<=rr<=4: col+=3
    if col:
      r0,r1=rooms[rr]; c0,c1=rooms[cc]
      for r in range(r0,r1+1):
        for c in range(c0,c1+1): out[r][c]=col
import json
print(json.dumps(out,separators=(',',':')))

